/**
 * useSubnetSync — Synchronises VNet subnet properties → child group nodes.
 *
 * When a Virtual Network node's `properties.subnets` array changes, this hook
 * creates, updates, or removes corresponding child group nodes on the diagram
 * so they appear as grey-bordered containers inside the VNet.
 */

import { useEffect, useRef } from 'react';
import type { AzureNode, AzureNodeData } from '../models';
import { dbg } from '../utils/debug';

/** Subnet item as stored in the VNet's properties.subnets array */
interface SubnetEntry {
  name: string;
  addressPrefix?: string;
  [key: string]: unknown;
}

const SUBNET_ICON = 'assets/azure-icons/networking/02742-icon-service-Subnet.svg';

/**
 * Derives a stable, deterministic child node ID from the VNet id + subnet
 * index so we can match existing nodes across renders.
 */
function subnetNodeId(vnetId: string, index: number): string {
  return `${vnetId}__subnet__${index}`;
}

export function useSubnetSync(
  nodes: AzureNode[],
  setNodes: React.Dispatch<React.SetStateAction<AzureNode[]>>,
) {
  // Track previous subnet state per VNet to avoid unnecessary updates.
  // Stores the full fingerprint as well as per-subnet prop/child names so
  // we can determine which side actually changed (prop edit vs child rename).
  const prevRef = useRef<Map<string, string>>(new Map());
  const prevNamesRef = useRef<Map<string, { prop: string; child: string }[]>>(new Map());

  useEffect(() => {
    const nextFingerprints = new Map<string, string>();
    const vnetNodes = nodes.filter(
      (n) => n.type === 'azureGroup' && (n.data as AzureNodeData).typeKey === 'virtual-networks',
    );

    // Build fingerprints that include both the VNet's subnet props AND the
    // current names of any existing subnet child nodes — so a rename on the
    // child triggers a reverse-sync back into the VNet properties.
    // Also include the VNet's measured dims so a resize re-flows children.
    for (const vnet of vnetNodes) {
      const data = vnet.data as AzureNodeData;
      const subnets = (data.properties?.subnets as SubnetEntry[] | undefined) ?? [];
      const childNames = subnets.map((_, i) => {
        const childId = subnetNodeId(vnet.id, i);
        const child = nodes.find((n) => n.id === childId);
        return (child?.data as AzureNodeData | undefined)?.name ?? '';
      });
      const w = Math.round(vnet.measured?.width ?? (vnet.width as number) ?? 0);
      const h = Math.round(vnet.measured?.height ?? (vnet.height as number) ?? 0);
      const fp = JSON.stringify({
        vnet: subnets.map((s) => ({ name: s.name, addressPrefix: s.addressPrefix })),
        children: childNames,
        dims: `${w}x${h}`,
      });
      nextFingerprints.set(vnet.id, fp);
    }

    // Check if anything changed
    let changed = false;
    if (nextFingerprints.size !== prevRef.current.size) {
      changed = true;
    } else {
      for (const [id, fp] of nextFingerprints) {
        if (prevRef.current.get(id) !== fp) {
          changed = true;
          break;
        }
      }
      // Also check for removed VNets
      if (!changed) {
        for (const id of prevRef.current.keys()) {
          if (!nextFingerprints.has(id)) {
            changed = true;
            break;
          }
        }
      }
    }

    if (!changed) return;
    dbg('useSubnetSync:fingerprintChanged', {
      prev: Object.fromEntries(prevRef.current),
      next: Object.fromEntries(nextFingerprints),
    });
    prevRef.current = nextFingerprints;

    setNodes((currentNodes) => {
      // Collect all existing subnet child IDs
      const existingSubnetIds = new Set(
        currentNodes
          .filter((n) => (n.id as string).includes('__subnet__'))
          .map((n) => n.id),
      );

      // Track VNet subnet-prop updates needed (reverse sync from renamed children)
      const vnetPropUpdates = new Map<string, SubnetEntry[]>();

      // Desired subnet nodes
      const desiredSubnets: AzureNode[] = [];
      const desiredIds = new Set<string>();

      for (const vnet of vnetNodes) {
        const data = vnet.data as AzureNodeData;
        const subnets = (data.properties?.subnets as SubnetEntry[] | undefined) ?? [];
        const updatedSubnets: SubnetEntry[] = subnets.map((s) => ({ ...s }));
        let propsChanged = false;

        // Compute layout: evenly space subnets inside VNet
        const vnetWidth = vnet.measured?.width ?? vnet.width ?? 250;
        const vnetHeight = vnet.measured?.height ?? vnet.height ?? 200;
        const headerHeight = 32; // group header area
        const padding = 12;
        const subnetCount = subnets.length;
        const availableWidth = vnetWidth - padding * 2;
        const availableHeight = vnetHeight - headerHeight - padding * 2;
        const subnetWidth = subnetCount > 0
          ? Math.max(120, (availableWidth - (subnetCount - 1) * 8) / subnetCount)
          : 120;
        const subnetHeight = Math.max(80, availableHeight);

        for (let i = 0; i < subnets.length; i++) {
          const subnet = subnets[i];
          const id = subnetNodeId(vnet.id, i);
          desiredIds.add(id);

          // Check if node already exists
          const existing = currentNodes.find((n) => n.id === id);
          const xPos = padding + i * (subnetWidth + 8);
          const yPos = headerHeight + padding;

          if (existing) {
            const existingData = existing.data as AzureNodeData;
            const childName = existingData.name;
            const propName = subnet.name || `Subnet ${i + 1}`;
            // Decide which side is authoritative: whichever changed since last sync.
            // If only the child name changed, propagate it back to the VNet props.
            // If the prop changed (or both / neither), the prop wins.
            const prevPair = prevNamesRef.current.get(vnet.id)?.[i];
            const propChanged = !prevPair || prevPair.prop !== propName;
            const childChanged = !prevPair || prevPair.child !== childName;
            let resolvedName = propName;
            if (childChanged && !propChanged && childName) {
              updatedSubnets[i] = { ...updatedSubnets[i], name: childName };
              propsChanged = true;
              resolvedName = childName;
            }
            dbg('useSubnetSync:resolveSubnet', {
              vnetId: vnet.id,
              index: i,
              propName,
              childName,
              prevPair,
              propChanged,
              childChanged,
              resolvedName,
              willOverwriteChild: resolvedName !== childName,
            });
            // Re-flow position and size to fit the (possibly resized) VNet
            desiredSubnets.push({
              ...existing,
              position: { x: xPos, y: yPos },
              style: { ...(existing.style ?? {}), width: subnetWidth, height: subnetHeight },
              data: {
                ...existing.data,
                name: resolvedName,
              },
            });
          } else {
            // Create new subnet child node
            desiredSubnets.push({
              id,
              type: 'azureGroup',
              position: { x: xPos, y: yPos },
              parentId: vnet.id,
              extent: 'parent',
              data: {
                typeKey: 'subnet',
                imagePath: SUBNET_ICON,
                name: subnet.name || `Subnet ${i + 1}`,
                location: '',
                useResourceGroupLocation: true,
                isValid: true,
                properties: {
                  addressPrefix: subnet.addressPrefix ?? '',
                },
              } satisfies AzureNodeData,
              style: { width: subnetWidth, height: subnetHeight },
            });
          }
        }

        if (propsChanged) {
          vnetPropUpdates.set(vnet.id, updatedSubnets);
        }
      }

      // IDs to remove: existing subnet nodes not in desired set, and not
      // belonging to a VNet that still exists
      const idsToRemove = new Set<string>();
      for (const id of existingSubnetIds) {
        if (!desiredIds.has(id)) {
          idsToRemove.add(id);
        }
      }

      // Build final node array:
      // 1. Keep all non-subnet nodes as-is (but apply VNet prop updates)
      // 2. Add the new/refreshed subnet nodes
      // 3. Drop stale subnet nodes
      const nonSubnets = currentNodes
        .filter((n) => !existingSubnetIds.has(n.id) && !idsToRemove.has(n.id))
        .map((n) => {
          const update = vnetPropUpdates.get(n.id);
          if (!update) return n;
          const d = n.data as AzureNodeData;
          return {
            ...n,
            data: {
              ...d,
              properties: {
                ...(d.properties ?? {}),
                subnets: update,
              },
            },
          };
        });

      const merged: AzureNode[] = [...nonSubnets, ...desiredSubnets];

      // React Flow v12 requires parents to appear before their children in the
      // nodes array. Otherwise a child's relative position is interpreted as
      // absolute (snaps to canvas top-left). Topologically sort by parentId.
      const byId = new Map(merged.map((n) => [n.id, n] as const));
      const visited = new Set<string>();
      const ordered: AzureNode[] = [];
      const visit = (n: AzureNode) => {
        if (visited.has(n.id)) return;
        if (n.parentId && byId.has(n.parentId)) {
          visit(byId.get(n.parentId)!);
        }
        visited.add(n.id);
        ordered.push(n);
      };
      for (const n of merged) visit(n);

      // Record the resolved per-subnet (prop, child) names so the next render
      // can detect which side actually changed and route updates correctly.
      const newPairs = new Map<string, { prop: string; child: string }[]>();
      for (const vnet of vnetNodes) {
        const data = vnet.data as AzureNodeData;
        const updated = vnetPropUpdates.get(vnet.id);
        const subnets = (updated ?? (data.properties?.subnets as SubnetEntry[] | undefined) ?? []);
        const pairs = subnets.map((s, i) => {
          const propName = s.name || `Subnet ${i + 1}`;
          const child = ordered.find((n) => n.id === subnetNodeId(vnet.id, i));
          const childName = (child?.data as AzureNodeData | undefined)?.name ?? propName;
          return { prop: propName, child: childName };
        });
        newPairs.set(vnet.id, pairs);
      }
      prevNamesRef.current = newPairs;

      return ordered;
    });
  }, [nodes, setNodes]);
}
